import UIKit

open class Proxy: Base {
    /// Typed parent object.
    public weak var parent: Parent?

    // Register known implementations
    public static func registerKnownImplementations() {
        register { Proxy(parent: $0) }
    }

    /// - parameter parent: Parent object.
    public init(parent: Parent) {
        self.parent = parent
    }
}
